namespace sv_491ae97b43b64b7a82fcfae1d0a5f599.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Each user gets their own instance, ensuring independent state.
/// </summary>
public class WarehouseStateService
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Harbor"),
    ];
}

namespace sv_491ae97b43b64b7a82fcfae1d0a5f599.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current user's circuit.
/// Raises an event whenever new alert data arrives so all subscribed components update.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning the count of items below minimum levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Subscribe to polling. Polling starts on the first subscriber and stops when
    /// the last subscriber unsubscribes.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            StartPolling();
        }
    }

    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            StopPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken cancellationToken)
    {
        // Fetch immediately on start
        await FetchAndNotifyAsync();

        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(cancellationToken))
                    break;
                await FetchAndNotifyAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task FetchAndNotifyAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private void HandleWarehouseChanged()
    {
        // When the warehouse changes, immediately re-fetch if polling is active
        if (_subscriberCount > 0)
        {
            _ = FetchAndNotifyAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        StopPolling();
    }
}

