<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-5">
            @CurrentWarehouseName
            <span class="text-muted">(@WarehouseState.SelectedWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            <span class="badge rounded-pill @BadgeClass fs-6">
                @AlertService.CurrentLowStockCount items below minimum level
            </span>
        </p>
        <p class="text-muted small">Auto-refreshes every 10 seconds. Last updated: @_lastUpdated.ToString("HH:mm:ss")</p>
    </div>
</div>

@code {
    private DateTime _lastUpdated = DateTime.Now;

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId).Name ?? "Unknown";

    private string BadgeClass => AlertService.CurrentLowStockCount > 5 ? "bg-danger" : "bg-warning text-dark";

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        AlertService.Subscribe();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleAlertDataChanged()
    {
        _lastUpdated = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        AlertService.Unsubscribe();
    }
}
